pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        bool referenceResult = c.supportsInterface(interfaceId);
        // The universal property: supportsInterface must agree with the disjunction
        // (interfaceId == type(IAccessControl).interfaceId || type(IERC165).interfaceId == interfaceId)
        // Since the reference implements ERC165, super.supportsInterface=type(IERC165).interfaceId == interfaceId.
        // The bug breaks this disjunction by using AND.
        bytes4 ierc165Id = 0x01ffc9a7;
        bool expectedDisjunction = (interfaceId == type(IAccessControl).interfaceId) || (ierc165Id == interfaceId);
        assertTrue(referenceResult == expectedDisjunction);
    }
}

