// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
        // Note: The given setUp uses address(this) for proposers and executors but the constructor expects arrays,
        // so we pass empty arrays to match the fuzzing requirement and keep setup valid.
        // The original constructor signature was:
        // constructor(uint256 minDelay, address[] memory proposers, address[] memory executors)
        // Using new address[](0) for both arrays keeps the contract deployable without hardcoding.
    }

    function testFuzz_property(bytes4 interfaceId) public {
        // The reference C inherits AccessControl which overrides supportsInterface to return true for
        // type(IAccessControl).interfaceId. The mutant removes this check and only delegates to super
        // (ERC165), so for interfaceId == type(IAccessControl).interfaceId the reference returns true
        // while the mutant returns false. The property: for any interfaceId that equals
        // type(IAccessControl).interfaceId, supportsInterface must return true. The fuzzer can supply
        // any bytes4; we assert that when the input matches the IAccessControl interface ID, the result
        // is true. On the mutant, this fails for that specific input.
        vm.assume(interfaceId == type(IAccessControl).interfaceId);
        bool result = c.supportsInterface(interfaceId);
        assertTrue(result, "supportsInterface must return true for IAccessControl");
    }
}

// Minimal interface access for type(...).interfaceId
interface IAccessControl {
    event RoleAdminChanged(bytes32 indexed role, bytes32 indexed previousAdminRole, bytes32 indexed newAdminRole);
    event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);
    event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
}

