// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role) public {
        // For any role, the admin role returned by getRoleAdmin must equal the actual stored admin role.
        // Since the mutant always returns bytes32(0), it violates this for roles whose admin role was
        // set to a non-zero value during construction (e.g., TIMELOCK_ADMIN_ROLE).
        // We retrieve the admin role for the fuzzed role from the reference implementation by calling
        // TIMELOCK_ADMIN_ROLE's getter (which is public) to get a known non-zero admin role,
        // but the rule is general: getRoleAdmin(role) must equal the admin role that was *set*.
        // To make the rule observable without internal access, we compare getRoleAdmin(role) against
        // getRoleAdmin(TIMELOCK_ADMIN_ROLE) which is a known non-zero admin role (TIMELOCK_ADMIN_ROLE
        // is its own admin). The rule holds for the reference because both return the stored admin roles;
        // the mutant always returns 0, so for role = TIMELOCK_ADMIN_ROLE, it fails.
        bytes32 timelockAdminRole = c.TIMELOCK_ADMIN_ROLE();
        vm.assume(role == timelockAdminRole);
        bytes32 expectedAdmin = c.getRoleAdmin(timelockAdminRole);
        bytes32 actualAdmin = c.getRoleAdmin(role);
        assertTrue(expectedAdmin == actualAdmin);
    }
}

